using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evaluation;

public class EvaluationTests : IAsyncLifetime
{
    private readonly ScenarioRunner _scenarioRunner;

    public EvaluationTests()
    {
        var reportingConfiguration = new ReportingConfiguration(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new GroundednessEvaluator(),
                new FluencyEvaluator()
            ]);

        _scenarioRunner = new ScenarioRunner(reportingConfiguration);
    }

    public Task InitializeAsync() => Task.CompletedTask;

    public async Task DisposeAsync() => await _scenarioRunner.DisposeAsync();

    [Theory]
    [MemberData(nameof(GetScenarios))]
    public async Task EvaluateScenario(string scenarioName, string userMessage, string context)
    {
        await using var scenarioRun = await _scenarioRunner.RunScenarioAsync(scenarioName);

        // In a full integration, this would call the chat client via the Aspire app host.
        // For now, provide the response to evaluate against the context.
        var response = await GetChatResponseAsync(userMessage);

        scenarioRun.Record(
            new TurnContext(userMessage, response, [new EvaluationContext(context)]));
    }

    private static Task<string> GetChatResponseAsync(string userMessage)
    {
        // TODO: Replace with actual call to the chat client through the Aspire app host.
        // Example using DistributedApplicationTestingBuilder:
        //   var appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        //   var app = await appHost.BuildAsync();
        //   await app.StartAsync();
        //   var chatClient = app.Services.GetRequiredService<IChatClient>();
        //   var result = await chatClient.GetResponseAsync(userMessage);
        return Task.FromResult("This is a placeholder response for evaluation scaffolding.");
    }

    public static IEnumerable<object[]> GetScenarios()
    {
        var scenariosDir = Path.Combine(Directory.GetCurrentDirectory(), "scenarios");
        if (!Directory.Exists(scenariosDir))
            yield break;

        foreach (var file in Directory.GetFiles(scenariosDir, "*.json"))
        {
            var scenario = System.Text.Json.JsonSerializer.Deserialize<EvaluationScenario>(
                File.ReadAllText(file));

            if (scenario is not null)
            {
                yield return [scenario.Name ?? Path.GetFileNameWithoutExtension(file),
                    scenario.UserMessage ?? string.Empty,
                    scenario.Context ?? string.Empty];
            }
        }
    }
}

public record EvaluationScenario(string? Name, string? UserMessage, string? Context);

